21	     * and its {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge} on that
22	     * figure. Null when there is none.
23	     */
24	    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
25	        if (claim.getSettledDue() != null) {
26	            return claim.getSettledDue();
27	        }
28	        BigDecimal base = base(claim, grades, rates);
29	        if (base == null || claim.isCorrection()) {
30	            return base;
31	        }
32	        BigDecimal due = overdue(claim, grades, rates)
33	                ? base.add(rates.lateCharge(base, graceBy(claim, grades, rates), claim.getRoundsBy()))
34	                : base;
35	        return rates.floored(due, claim.getDate());
36	    }
37	
38	    /**
39	     * A claim's figure before any late charge or floor: while bound by a statement (and not PENDING, which is
40	     * never bound), the figure bound then; otherwise its {@link #rateFigure rate figure}. Null when there is
41	     * none. A statement binds this figure, never the late charge or the floor.
42	     */
43	    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
44	        if (bound(claim)) {
45	            return claim.getStatedDue();
46	        }
47	        return rateFigure(claim, grades, rates);
48	    }
