50	    /**
51	     * The amount at the rate in force on the claim's date for its person's grade in force then, rounded by
52	     * its date (a correction by the date its rounding goes by), see {@link RateTable#rounding}; no floor. Null when no rate is.
53	     */
54	    private static BigDecimal rateFigure(Claim claim, Grades grades, RateTable rates) {
55	        String grade = grades.on(claim.getDate());
56	        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
57	                rates.rounding(claim.getRoundsBy()))
58	                : rates.figure(claim.getAmount(), grade, claim.getDate());
59	    }
60	
61	    /**
62	     * The figure the claim would have today as an OPEN claim bound by no statement: its rate figure plus the
63	     * late charge it has today on that figure when its due-by plus its grace has passed, but at least the floor in force on
64	     * its date; a correction has neither floor nor late charge. Null when there is none. Re-settling a claim
65	     * fixes its due at this figure.
66	     */
67	    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
68	        BigDecimal base = rateFigure(claim, grades, rates);
69	        if (base == null || claim.isCorrection()) {
70	            return base;
71	        }
72	        LocalDate graceBy = graceBy(claim, grades, rates);
73	        BigDecimal due = graceBy.isBefore(rates.today())
74	                ? base.add(rates.lateCharge(base, graceBy, claim.getRoundsBy()))
75	                : base;
76	        return rates.floored(due, claim.getDate());
77	    }
