79	    /** Whether a statement binds the claim's figure: it is stated and not PENDING. */
80	    public static boolean bound(Claim claim) {
81	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
82	    }
83	
84	    /**
85	     * Whether the claim is overdue: OPEN or PENDING, not {@link #deferred deferred}, and due by a date before
86	     * the sheet's today (its due-by, fixed when it was added, plus its {@link #graceBy grace}).
87	     */
88	    public static boolean overdue(Claim claim, Grades grades, RateTable rates) {
89	        return claim.getStatus().unpaid() && !deferred(claim, rates.today())
90	                && graceBy(claim, grades, rates).isBefore(rates.today());
91	    }
92	
93	    /**
94	     * The date a claim's overdue and late charge count from: its due-by plus the grace days in force on its
95	     * date for its person's grade in force then (none: its due-by). The due-by shown is unchanged.
96	     */
97	    public static LocalDate graceBy(Claim claim, Grades grades, RateTable rates) {
98	        return claim.getDueBy().plusDays(rates.settings().grace(grades.on(claim.getDate()), claim.getDate()));
