142	     * Whether the person's holds or retirement leave the claim out of the live totals: unless a statement
143	     * binds it, an OPEN claim dated within a hold, and an OPEN or PENDING claim once the sheet's today has
144	     * reached the person's retirement date.
145	     */
146	    private static boolean leftOut(Claim claim, Holds holds, LocalDate today) {
147	        return !bound(claim) && ((claim.getStatus() == ClaimStatus.OPEN && holds.on(claim.getDate()))
148	                || (claim.getStatus().unpaid() && holds.retiredOn(today)));
149	    }
