152	     * Whether the person is active on the sheet's today: they have an OPEN or PENDING claim that counts (see
153	     * {@link #counts}) dated within the 30 days up to and including that today.
154	     */
155	    public static boolean active(List<Claim> claims, Holds holds, LocalDate today) {
156	        LocalDate from = today.minusDays(29);
157	        return claims.stream().anyMatch(c -> (c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
158	                && counts(c, holds, today) && !c.getDate().isBefore(from) && !c.getDate().isAfter(today));
