164	     * {@code fromDays} to {@code toDays} inclusive (0.00 with none); a claim with no figure is skipped.
165	     */
166	    public static BigDecimal aged(Grades grades, List<Claim> claims, RateTable rates, Holds holds, long fromDays,
167	            long toDays) {
168	        LocalDate today = rates.today();
169	        return sum(grades, claims.stream().filter(c -> c.getStatus().unpaid() && counts(c, holds, today))
170	                .filter(c -> {
171	                    long age = Math.max(0, ChronoUnit.DAYS.between(c.getDate(), today));
172	                    return age >= fromDays && age <= toDays;
