      if (this.gradeProofTouched[g] && threshold !== '' && !LIMIT.test(threshold)) {
        this.settingsError.set(`Enter a proof threshold for grade ${g} of 0.00 or more, with up to two decimals, or leave it blank for the sheet's.`);
